app.json:
{
  "budget": {
    "per_run": 0.05
  },
  "capabilities": {
    "records": {
      "company": "r",
      "contact": "rw",
      "daily_desk_brief": "rw",
      "deal": "rw",
      "meeting": "rw",
      "meeting_brief": "rw",
      "message": "r",
      "note": "rw"
    }
  },
  "commands": [
    {
      "id": "prepare-external-meeting-brief",
      "label": "Prepare external meeting brief",
      "for": "meeting",
      "run": "prepare-external-meeting-brief",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "draft-follow-up-from-transcript",
      "label": "Draft follow up from transcript",
      "for": "meeting",
      "run": "draft-follow-up-from-transcript",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "move-to-proposal",
      "label": "Move to Proposal",
      "for": "deal",
      "confirm": "Move this record to Proposal?",
      "do": [
        {
          "lifecycle.transition": {
            "id": "$record.id",
            "transition": "propose",
            "type": "deal"
          }
        }
      ]
    },
    {
      "id": "move-to-negotiation",
      "label": "Move to Negotiation",
      "for": "deal",
      "confirm": "Move this record to Negotiation?",
      "do": [
        {
          "lifecycle.transition": {
            "id": "$record.id",
            "transition": "negotiate",
            "type": "deal"
          }
        }
      ]
    },
    {
      "id": "mark-won",
      "label": "Mark Won",
      "for": "deal",
      "confirm": "Move this record to Won?",
      "do": [
        {
          "lifecycle.transition": {
            "id": "$record.id",
            "transition": "win",
            "type": "deal"
          }
        }
      ]
    },
    {
      "id": "mark-lost",
      "label": "Mark Lost",
      "for": "deal",
      "confirm": "Move this record to Lost?",
      "do": [
        {
          "lifecycle.transition": {
            "id": "$record.id",
            "transition": "lose",
            "type": "deal"
          }
        }
      ]
    }
  ],
  "id": "01M8D6XZ9BKZQCX6VNX5ETJJHH",
  "kit": 2,
  "name": "Account Desk",
