      "common": "organization",
      "fields": {
        "industry": {
          "type": "text"
        },
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "website": {
          "type": "url"
        }
      },
      "present": {
        "title": "name",
        "link": "website"
      },
      "title": "name"
    },
    "contact": {
      "common": "person",
      "fields": {
        "email": {
          "type": "email"
        },
        "name": {
          "type": "text",
          "required": true
        },
        "organization": {
          "type": "ref",
          "to": "company"
        },
        "phone": {
          "type": "phone"
