      "fields": {
        "body": {
          "type": "longtext"
        },
        "deal": {
          "type": "ref",
          "to": "deal"
        },
        "from": {
          "type": "ref",
          "to": "contact"
        },
        "received_at": {
          "type": "datetime"
        },
        "subject": {
          "type": "text"
        },
        "thread_key": {
          "type": "text"
        }
