        "meeting": {
          "type": "ref",
          "to": "meeting"
        },
        "title": {
          "type": "text",
          "required": true
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "deal",
          "meeting"
        ]
      },
      "title": "title"
