      "id": "explain-deal-risks",
      "on": "record.changed",
      "type": "deal",
      "when": "changed(\"name\") || changed(\"risk\") || changed(\"stage\") || changed(\"close_date\") || changed(\"next_step\")",
      "run": "explain-deal-risks"
    },
