      "id": "propose-stage-and-next-step-changes",
      "on": "record.changed",
      "type": "deal",
      "when": "changed(\"name\") || changed(\"stage\") || changed(\"next_step\") || changed(\"risk_explanation\")",
      "run": "propose-stage-and-next-step-changes"
    },
    {
      "id": "summarize-today-s-account-priorities",
      "on": "schedule",
      "cron": "0 8 * * *",
      "run": "summarize-today-s-account-priorities"
    }
  ],
  "version": 1
