runs/draft-follow-up-from-transcript.yam:
{
  "run": "draft-follow-up-from-transcript",
  "title": "Draft follow up from transcript",
  "budget": {
    "per_run": 0.05
  },
  "params": {
    "subject": {
      "type": "ref",
      "to": "meeting"
    }
  },
  "steps": [
    {
      "id": "draft",
      "ai": {
        "prompt": "Save an unsent follow-up note linked to the selected meeting and its deal. Draft a customer-ready recap of what was agreed, action items and owners, and dates only when stated in the transcript. If there is no transcript, flag that instead of inventing a recap.\nmeeting.transcript: {{params.subject[\"transcript\"]}}\nmeeting.name: {{params.subject[\"name\"]}}\nmeeting.attendees: {{params.subject[\"attendees\"]}}\nmeeting.deal: {{params.subject[\"deal\"]}}\ndeal.name: {{params.subject[\"deal\"] == null ? null : params.subject[\"deal\"][\"name\"]}}\ndeal.next_step: {{params.subject[\"deal\"] == null ? null : params.subject[\"deal\"][\"next_step\"]}}",
        "output": {
          "type": "string"
        },
        "example": "Body example 1"
      }
    },
    {
      "id": "save",
      "records.create": {
        "type": "note",
        "set": {
          "body": "$steps.draft.output",
          "meeting": "$params.subject.id",
          "title": "Draft follow up from transcript"
        }
      }
    }
  ]
}

runs/explain-deal-risks.yaml:
{
  "run": "explain-deal-risks",
  "budget": {
    "per_run": 0.05
  },
  "steps": [
    {
      "id": "derive",
      "ai": {
        "prompt": "Explain what could put the deal at risk and why. Cite relevant evidence from this deal's mail and meeting transcripts, distinguish facts from assumptions, and identify what the owner should verify. Preserve the existing risk notes.\ndeal.name: {{record[\"name\"]}}\ndeal.risk: {{record[\"risk\"]}}\ndeal.stage: {{record[\"stage\"]}}\ndeal.close_date: {{record[\"close_date\"]}}\ndeal.next_step: {{record[\"next_step\"]}}\nmeeting.deal: {{records(\"meeting\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"deal\"])}}\nmeeting.transcript: {{records(\"meeting\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"transcript\"])}}\nmessage.deal: {{records(\"message\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"deal\"])}}\nmessage.received_at: {{records(\"message\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"received_at\"])}}\nmessage.subject: {{records(\"message\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"subject\"])}}\nmessage.body: {{records(\"message\").filter(row, row[\"deal\"] != null \u0026\u0026 row[\"deal\"].id == record.id).map(row, row[\"body\"])}}",
        "output": {
          "type": "string"
        },
        "example": "Risk explanation example 1"
      }
    },
    {
      "id": "save",
      "records.update": {
        "type": "deal",
        "id": "$record.id",
        "set": {
          "risk_explanation": "$steps.derive.output"
        }
      }
    }
  ]
}

