        "output": {
          "type": "string"
        },
        "example": "Proposed crm changes example 1"
      }
    },
    {
      "id": "save",
      "records.update": {
        "type": "deal",
        "id": "$record.id",
        "set": {
          "proposed_crm_changes": "$steps.derive.output"
        }
      }
    }
  ]
}

