        "output": {
          "type": "string"
        },
        "example": "Summary example 1"
      }
    },
    {
      "id": "save",
      "records.create": {
        "type": "daily_desk_brief",
        "set": {
          "summary": "$steps.draft.output",
          "title": "Summarize today's account priorities"
